  "codebook": {
    "definition": "Credit-claiming refers to statements in which a senator explicitly or implicitly claims personal or legislative responsibility for a desirable outcome. This includes securing federal funding, grants, or resources for their state or constituents, successfully passing legislation, successfully adding amendments to a bill, or successfully prompting a favorable administrative action or policy change.",
    "clarification": "A text should be classified as credit-claiming if the senator announces a specific federal grant or funding for their state (as the act of announcing the grant themselves implies their involvement as the provider), mentions passing an amendment or bill they authored, or highlights their specific intervention that led to a positive outcome (such as writing a letter or holding a meeting that resulted in an agency action). Mentioning past legislative or funding victories also counts as credit-claiming.",
    "positive_examples": [
      {
        "document_id": "3482",
        "explanation": "The senator announces that a local county has been awarded a federal grant and highlights her position on the appropriations committee that funds the program, making herself the deliverer of the federal benefit."
      },
      {
        "document_id": "3252",
        "explanation": "The senator announces that the Senate has adopted his amendment, explicitly taking credit for a successful legislative accomplishment."
      },
      {
        "document_id": "2382",
        "explanation": "The senator points out that she successfully intervened with the Department of Homeland Security and cut red tape to allow a child to receive surgery, directly claiming responsibility for the agency's favorable action."
      }
    ],
    "negative_clarification": "A text should NOT be classified as credit-claiming if it only expresses support or opposition to a policy, announces the introduction of a bill without mentioning its passage or inclusion in larger legislation, calls on an agency to act without reporting a successful outcome, or announces public meetings, town halls, or symbolic memorial resolutions. Co-sponsoring a bill that hasn't passed or simply receiving an award does not count as claiming credit for a substantive policy or constituent outcome.",
    "negative_examples": [
      {
        "document_id": "453",
        "explanation": "The senator explains his rationale for voting against arbitrary dates for withdrawal from Iraq. This is position-taking on a roll call vote, not claiming credit for a tangible benefit or passed law."
      },
      {
        "document_id": "57",
        "explanation": "The senator announces the introduction of a piece of legislation and outlines its provisions. Because the bill is merely being introduced and no passage or adoption is claimed, it is classified as position-taking."
      },
      {
        "document_id": "299",
        "explanation": "The senator is recognized with a 'Hero of the Taxpayer' award by an interest group based on his voting record. Receiving an award for a voting record is not claiming credit for delivering government resources or passing a law."
      }
    ]
  }
}
